package com.ptms.repository; import com.ptms.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*; public interface ParkingTicketRepository extends JpaRepository<ParkingTicket,Long>{Optional<ParkingTicket> findByBarcodeIgnoreCase(String b); List<ParkingTicket> findByStatusOrderByDurationHoursAscTicketNumberAsc(TicketStatus s); long countByStatus(TicketStatus s); long countByStatusAndDurationHours(TicketStatus s,int h); boolean existsByDurationHoursAndTicketNumberCycleAndTicketNumber(int h,String cycle,Integer n); @Query("select max(t.ticketNumber) from ParkingTicket t where t.durationHours=:hours and t.ticketNumberCycle=:cycle") Integer maxTicketNumber(@Param("hours") int hours,@Param("cycle") String cycle);}
